// Decides what happens to this enrollment this run: exit early if the
// contact replied since we last emailed them, mark complete if every
// step's already sent, or flag it as a candidate for the next step
// (still needs a "is it actually due yet" check downstream).
const row = $input.item.json;
const emailLogs = row.email_logs || [];
const referenceTime = new Date(row.last_step_sent_at || row.enrolled_at).getTime();

const replied = emailLogs.some(
  (log) => log && log.type === 'received' && new Date(log.sent_at).getTime() > referenceTime
);

if (replied && row.exit_on_reply) {
  return [{ json: { ...row, action: 'exit_reply' } }];
}

const nextStep = row.current_step + 1;
if (nextStep > row.total_steps) {
  return [{ json: { ...row, action: 'complete' } }];
}

return [{ json: { ...row, action: 'maybe_send', nextStep } }];

// delay_days counts from enrollment for step 1, or from the previous
// step's send time for every step after that.
const step = $input.item.json;
const enrollment = $('Check Reply & Determine Action').item.json;

const referenceTime = new Date(enrollment.last_step_sent_at || enrollment.enrolled_at);
const dueAt = new Date(referenceTime.getTime() + step.delay_days * 24 * 60 * 60 * 1000);
const due = new Date() >= dueAt;

function fill(template) {
  return (template || '')
    .replace(/{{\s*first_name\s*}}/gi, enrollment.first_name || 'there')
    .replace(/{{\s*last_name\s*}}/gi, enrollment.last_name || '');
}

return [{
  json: {
    due,
    enrollmentId: enrollment.enrollment_id,
    nextStep: enrollment.nextStep,
    to: enrollment.email,
    subject: fill(step.email_subject),
    body: fill(step.email_body),
  },
}];
